const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches){document.body.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));const petals=document.querySelector('.petals');for(let i=0;i<12;i++){const petal=document.createElement('i');petal.className='petal';petal.style.left=`${i*8.5}%`;petal.style.animationDelay=`${-i*2.3}s`;petal.style.animationDuration=`${14+i%5*2}s`;petals.append(petal)}let ticking=false;const art=document.querySelector('.hero-art');window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{if(!reduced.matches&&window.scrollY<window.innerHeight*1.3)art.style.transform=`translateY(${Math.min(window.scrollY*.18,150)}px)`;ticking=false});ticking=true}},{passive:true})}
document.querySelector('#calendar').addEventListener('click',()=>{const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Siddhant and Aanchal//Wedding//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:siddhant-aanchal-wedding-20270309','DTSTAMP:20260918T000000Z','DTSTART;VALUE=DATE:20270309','DTEND;VALUE=DATE:20270311','SUMMARY:Siddhant & Aanchal — Wedding Celebrations','DESCRIPTION:9 March: Ring ceremony\\, Mehendi\\, Tilak and Sangeet. 10 March: Haldi and Wedding. Timings and venue to follow.','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Siddhant-and-Aanchal-Wedding.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#calendar-status').textContent='Your calendar invitation is ready to add.'});

const entry=document.querySelector('.entry');
if(!location.hash){entry.showModal();}
function openInvitation(skip=false){if(skip||reduced.matches){entry.close();return;}entry.classList.add('opening');setTimeout(()=>{entry.close();document.querySelector('.primary').focus({preventScroll:true});},1550);}
document.querySelector('.entry-open').addEventListener('click',()=>openInvitation());
document.querySelector('.entry-skip').addEventListener('click',()=>openInvitation(true));
